package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaMlDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rooster_donkey" to DuaText("കോഴിയുടെയോ കഴുതയുടെയോ ശബ്ദം കേൾക്കുന്നു", "അല്ലാഹുവേ, ഞാൻ നിന്നോടു നിൻറെ അനുഗ്രഹം (കോഴി) ചോദിക്കുന്നു. ശപിക്കപ്പെട്ട (കഴുത) ഷൈത്താൻറെ പക്കൽ നിന്ന് ഞാൻ അല്ലാഹുവിങ്കൽ അഭയം തേടുന്നു.", "ഒരു കോഴി അല്ലാഹുവിൻറെ അനുഗ്രഹം തേടുന്നത് കേൾക്കുമ്പോൾ; കഴുതയുടെ കുണ്ണ കേൾക്കുമ്പോൾ ഷൈത്താനിൽ നിന്ന് അഭയം തേടുക.", "കോഴി ഒരു മാലാഖയെയും കഴുത ഒരു പിശാചിനെയും കാണുന്നു."),
        "dua_something_liked" to DuaText("പ്രശംസനീയമായ എന്തെങ്കിലും കാണുന്നത് (തിന്മയ്ക്ക് എതിരെ)", "അല്ലാഹു ഉദ്ദേശിച്ചതെന്താണോ അത്. അല്ലാഹുവേ, നീ അനുഗ്രഹിക്കണമേ.", "ഒരാളുടെ പ്രശംസനീയമായ എന്തെങ്കിലും കാണുമ്പോൾ, അനുഗ്രഹത്തിനായി പ്രാർത്ഥിക്കുക.", "അനുഗ്രഹത്തിനായി പ്രാർത്ഥിക്കുന്നത് ദുശ്ശീലത്തെ തടയുന്നു."),
        "dua_sell_buy_debt_repaid" to DuaText("ഒരു കടം തിരിച്ചടയ്ക്കുമ്പോൾ", "നിങ്ങളുടെ കുടുംബത്തിലും സമ്പത്തിലുമായി അല്ലാഹു നിങ്ങളെ അനുഗ്രഹിക്കട്ടെ.", "കടം തിരിച്ചടയ്ക്കുമ്പോൾ വായ്പ നൽകുന്നയാൾക്ക്.", "വായ്പയുടെ തിരിച്ചടവ് നന്ദിയും തിരിച്ചടവുമാണ്."),
        "dua_talbiyah" to DuaText("തൽബിയ", "അല്ലാഹുവേ, ഞാൻ ഇവിടെയുണ്ട്. ഞാൻ ഇവിടെയുണ്ട്. നിനക്ക് ഒരു പങ്കാളിയും ഇല്ല. ഞാൻ ഇവിടെയുണ്ട്. തീർച്ചയായും എല്ലാ സ്തുതിയും അനുഗ്രഹവും ആധിപത്യവും നിനക്കുള്ളതാണ്. നിനക്ക് ഒരു പങ്കാളിയും ഇല്ല.", "ഇഹ്റാമിൽ പ്രവേശിച്ച ശേഷം ഉറക്കെ.", "ഹജ്ജ്, ഉമ്ര എന്നിവയുടെ ചിഹ്നം."),
        "dua_yamani_hajar" to DuaText("റുക്ക്ൻ യമാനിക്കും ഹജർ അസ്വാദിനും ഇടയിൽ", "ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങൾക്ക് ഇഹലോകത്ത് നന്മയും പരലോകത്ത് നന്മയും നൽകുകയും നരകശിക്ഷയിൽ നിന്ന് ഞങ്ങളെ സംരക്ഷിക്കുകയും ചെയ്യേണമേ.", "തവാഫിൽ, യെമൻ കോർണറിനും ബ്ലാക്ക് സ്റ്റോണിനും ഇടയിൽ.", "നബി (സ) ഇത് തവാഫിലെ ഈ സ്ഥലത്ത് പാരായണം ചെയ്തു."),
        "dua_safa_marwa" to DuaText("സഫയിലും മാർവാഹിലും", "അല്ലാഹുവല്ലാതെ ആരാധിക്കപ്പെടാൻ ആർക്കും അവകാശമില്ല. അവന്നാകുന്നു ആധിപത്യം. സ്തുതിയും അവന്നാകുന്നു. എല്ലാ കാര്യങ്ങളിലും അവൻറെ കഴിവുണ്ട്. അല്ലാഹുവല്ലാതെ ആരാധിക്കപ്പെടാൻ ആർക്കും അവകാശമില്ല. അവൻ തൻറെ വാഗ്ദാനം നിറവേറ്റുകയും തൻറെ ദാസനെ സഹായിക്കുകയും, സഖ്യകക്ഷികളെ പരാജയപ്പെടുത്തുകയും ചെയ്തു.", "സഫ കയറുകയും ഖിബ്ലയിലേക്ക് അഭിമുഖീകരിക്കുകയും ചെയ്യുക (മൂന്ന് തവണ).", "സഫയിലും മർവാഹിലും പ്രവാചകൻറെ ധിക്കർ."),
        "dua_arafah" to DuaText("അറഫയുടെ ദിനത്തിലെ ഏറ്റവും മികച്ച ദുആ", "അല്ലാഹുവല്ലാതെ ആരാധനയ്ക്ക് അർഹനായി മറ്റാരുമില്ല. അവൻ ഏകനാണ്, അവന് പങ്കാളികളില്ല. അവന്നാകുന്നു ആധിപത്യം. സ്തുതിയും അവന്നാകുന്നു. അവൻ എല്ലാ കാര്യത്തിനും കഴിവുള്ളവനാകുന്നു.", "അറഫയുടെ ദിവസം-ഏറ്റവും മികച്ച ദുആ.", "അറഫാദിനത്തിലെ ദുആയാണ് ഏറ്റവും മികച്ച ദുആ, ഏറ്റവും മികച്ച വാക്കുകൾ ഇവയാണ്."),
        "dua_takbeer_tashreeq" to DuaText("തക്ബീർ-ഇ-തഷ്രീഖ്", "അല്ലാഹു ഏറ്റവും വലിയവനാണ്, അല്ലാഹു ഏറ്റവും വലിയവനാണ്. അല്ലാഹുവല്ലാതെ ദൈവമില്ല. അല്ലാഹു ഏറ്റവും വലിയവനാണ്, അല്ലാഹു ഏറ്റവും വലിയവനാണ്, എല്ലാ സ്തുതികളും അല്ലാഹുവിനാണ്.", "9-ാം ധുൽ-ഹിജ്ജയിലെ ഫജ്ർ മുതൽ 13-ാം ധുൽ-ഹിജ്ജയിലെ അസർ വരെയുള്ള എല്ലാ നിർബന്ധിത പ്രാർത്ഥനകൾക്കും ശേഷം.", "അലിയിൽ നിന്നും ഇബ്നു മസൂദ് (റ) ൽ നിന്നും-ഹനാഫികൾ പറയുന്നതനുസരിച്ച് വാജിബ്."),
        "dua_zamzam" to DuaText("സംസം കുടിക്കുന്നു", "അല്ലാഹുവേ, ഗുണകരമായ അറിവും സമൃദ്ധമായ ഉപജീവനവും എല്ലാ രോഗങ്ങളിൽ നിന്നുമുള്ള പരിഹാരവും ഞാൻ നിന്നോടു ചോദിക്കുന്നു.", "സാംസം കുടിക്കുമ്പോൾ നിങ്ങൾ ഉദ്ദേശിക്കുന്നതെന്തിനും വേണ്ടി ദുവാ ഉണ്ടാക്കുക.", "സംസം എന്തിനും കുടിച്ചതിന് വേണ്ടിയാണ് (ഇബ്നു മജാഹ് 3062)."),
        "dua_q_ma_khalaqta_batila" to DuaText("സൃഷ്ടിയെക്കുറിച്ച് ചിന്തിക്കുന്നു", "ഞങ്ങളുടെ രക്ഷിതാവേ, നീ ഇതൊന്നും വെറുതെ സൃഷ്ടിച്ചതല്ല. നീ പരിശുദ്ധൻ. അതിനാൽ നരകശിക്ഷയിൽ നിന്ന് ഞങ്ങളെ സംരക്ഷിക്കേണമേ.", "ആകാശങ്ങളുടെയും ഭൂമിയുടെയും സൃഷ്ടിയെക്കുറിച്ച് ചിന്തിക്കുന്നവരുടെ ദുആ.", "വിവേകമുള്ളവരുടെ ദുആ (ഉലുൽ-അൽബാബ്)."),
        "dua_q_sami_na_munadiyan" to DuaText("വിശ്വാസത്തിലേക്ക് വിളിച്ചയാളെ നാം കേട്ടു.", "ഞങ്ങളുടെ രക്ഷിതാവേ, നിൻറെ രക്ഷിതാവിൽ വിശ്വസിക്കുവിൻ എന്ന് വിളിച്ചുപറയുന്ന ഒരുത്തനെ ഞങ്ങൾ കേട്ടു. ഞങ്ങൾ വിശ്വസിച്ചു. ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങളുടെ പാപങ്ങൾ നീ പൊറുത്തുതരേണമേ. ഞങ്ങളുടെ ദുഷ്കർമ്മങ്ങൾ നീ ഞങ്ങളിൽനിന്ന് നീ നീ നീ നീ നീ നീ നീ നീ നീ നീ നീ നീ നീ നീ നീ നീ നീ നീ നീ നീ ഞങ്ങളെ വിട്ടുപിരിഞ്ഞുകളയണമേ. സൽകർമ്മക്കാർക്കൊപ്പം ഞങ്ങളെയും നീ മരിപ്പിക്കണമേ.", "വിശ്വാസത്തിനും നീതിമാന്മാരുടെ ഇടയിൽ മരിക്കുന്നതിനും വേണ്ടിയുള്ള ഒരു ദുആ.", "ക്ഷമയ്ക്കും നല്ല അവസാനത്തിനുമുള്ള ഒരു ദുആ."),
        "dua_q_atina_ma_waadtana" to DuaText("നിങ്ങൾ വാഗ്ദാനം ചെയ്തത് ഞങ്ങൾക്ക് നൽകുക.", "ഞങ്ങളുടെ രക്ഷിതാവേ, നിൻറെ ദൂതൻമാർ വഴി നീ ഞങ്ങൾക്ക് വാഗ്ദാനം ചെയ്തതൊക്കെ ഞങ്ങൾക്ക് നീ നൽകുകയും ഉയിർത്തെഴുന്നേൽപിൻറെ നാളിൽ നീ ഞങ്ങളെ അപമാനിക്കാതിരിക്കുകയും ചെയ്യേണമേ. തീർച്ചയായും നീ നിൻറെ വാഗ്ദാനം ലംഘിക്കുന്നില്ല.", "ഉയിർത്തെഴുന്നേൽപിൻറെ നാളിൽ അപമാനത്തിൽ നിന്ന് അഭയം തേടുക.", "പരലോകത്ത് ബഹുമാനം തേടുന്നു."),
        "dua_q_israfana" to DuaText("ഞങ്ങളുടെ അമിതമായ കാര്യങ്ങൾ ക്ഷമിക്കുക.", "ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങളുടെ പാപങ്ങളും ഞങ്ങളുടെ കാര്യങ്ങളിലെ അതിക്രമങ്ങളും നീ ക്ഷമിക്കണമേ. ഞങ്ങളുടെ കാലുകൾ ഉറപ്പിക്കുകയും സത്യനിഷേധികൾക്കെതിരെ ഞങ്ങളെ സഹായിക്കുകയും ചെയ്യേണമേ.", "മുൻ പ്രവാചകന്മാരുടെ കൂട്ടാളികൾ.", "സ്ഥിരതയ്ക്കും ക്ഷമയ്ക്കും വേണ്ടിയുള്ള ഒരു ദുആ."),
        "dua_q_jamiun_nas" to DuaText("നിങ്ങൾ മനുഷ്യരാശിയെ ശേഖരിക്കും.", "ഞങ്ങളുടെ രക്ഷിതാവേ, യാതൊരു സംശയവുമില്ലാത്ത ഒരു ദിവസം നീ മനുഷ്യരെ ഒരുമിച്ചുകൂട്ടും. തീർച്ചയായും അല്ലാഹു തൻറെ വാഗ്ദാനം ലംഘിക്കുകയില്ല.", "ഉയിർത്തെഴുന്നേൽപിൻറെ നാളിൽ ഉറപ്പുള്ളവർ.", "അറിവിൽ ഉറച്ചുനിൽക്കുന്നവരുടെ ദുവാ."),
        "dua_q_maash_shahidin" to DuaText("സാക്ഷികളുടെ ഇടയിൽ ഞങ്ങളെ എഴുതുക", "ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങൾ വിശ്വസിച്ചിരിക്കുന്നു. അതിനാൽ ഞങ്ങളെ സാക്ഷികളുടെ ഇടയിൽ എഴുതുക.", "സത്യം തിരിച്ചറിയുകയും വിശ്വസിക്കുകയും ചെയ്തവരുടെ ദുആ.", "ഒരാളുടെ വിശ്വാസം സ്വീകരിക്കുന്നതിനുള്ള ഒരു ദുആ."),
        "dua_q_la_tajalna_zalimin" to DuaText("തെറ്റുകാരോടൊപ്പമല്ല", "ഞങ്ങളുടെ രക്ഷിതാവേ, നീ ഞങ്ങളെ അക്രമികളായ ജനക്കൂട്ടത്തിൻറെ കൂടെ നിർത്തരുത്.", "അൽ-അറഫിലെ ജനങ്ങളുടെ ദുആ.", "തെറ്റുകാരുടെ വിധിയിൽ നിന്ന് അഭയം തേടുക."),
        "dua_q_tawaffana_muslimin" to DuaText("മുസ്ലീങ്ങൾ എന്ന നിലയിൽ ക്ഷമയും മരണവും", "ഞങ്ങളുടെ കർത്താവേ, ഞങ്ങളുടെമേൽ ക്ഷമ ചെലുത്തുകയും മുസ്ലീങ്ങളായി ഞങ്ങളെ മരിപ്പിക്കുകയും ചെയ്യേണമേ.", "ഫറവോന്റെ മാന്ത്രികർ വിശ്വസിച്ചപ്പോൾ അവർ വിശ്വസിച്ചവരുടെ ദുആ.", "വിചാരണയിൽ ക്ഷമയും വിശ്വാസത്തിൽ അവസാനിക്കുന്ന അവസ്ഥയും."),
        "dua_q_la_tajalna_fitnah" to DuaText("അടിച്ചമർത്തലുകാരുടെ വിചാരണയല്ല", "ഞങ്ങൾ അല്ലാഹുവിൽ ആശ്രയിക്കുന്നു. ഞങ്ങളുടെ രക്ഷിതാവേ, നീ ഞങ്ങളെ അക്രമികളായ ജനങ്ങൾക്ക് ഒരു പരീക്ഷണമാക്കി മാറ്റരുത്. നിൻറെ കാരുണ്യത്താൽ സത്യനിഷേധികളിൽ നിന്ന് ഞങ്ങളെ രക്ഷിക്കേണമേ.", "മൂസ (അ. സ.) ജനതയുടെ ദുആ.", "അടിച്ചമർത്തലിൽ നിന്നും അടിച്ചമർത്തുന്നവരിൽ നിന്നും രക്ഷയ്ക്കുള്ള ഒരു ദുആ."),
        "dua_q_nuh_ma_laysa_li" to DuaText("ക്ഷമിക്കാനുള്ള നൂഹ് (അ. സ.)-ൻറെ ദുആ", "എൻറെ രക്ഷിതാവേ, എനിക്കറിയാത്തതിനെക്കുറിച്ച് നിന്നോടു ചോദിക്കുന്നതിൽ നിന്ന് ഞാൻ നിന്നിൽ അഭയം തേടുന്നു. നീ എന്നോട് ക്ഷമിക്കുകയും എന്നോട് കരുണ കാണിക്കുകയും ചെയ്തില്ലെങ്കിൽ ഞാൻ നഷ്ടം സംഭവിച്ചവരുടെ കൂട്ടത്തിലായിരിക്കും.", "നൂഹ് (അ. സ.) നബിയുടെ അനുതാപത്തിൻറെ ദുആ.", "ശരിയായ പെരുമാറ്റത്തോടെ ചോദിക്കുന്നതിനുള്ള ഒരു പാഠം."),
        "dua_q_mudkhala_sidq" to DuaText("സത്യത്തിൻ്റെ പ്രവേശനവും പുറത്തേക്കുമുള്ള വഴിയും", "എൻറെ രക്ഷിതാവേ, എന്നെ സത്യവുമായി പ്രവേശിക്കുകയും സത്യവുമായി പുറത്തുകടക്കുകയും ചെയ്യേണമേ. നിൻറെ പക്കൽ നിന്ന് എനിക്ക് ഒരു സഹായ അധികാരം നൽകുകയും ചെയ്യേണമേ.", "ഒരു പുതിയ ജോലിയിൽ പ്രവേശിക്കുന്നതിന് മുമ്പ്, വീട്ടിലോ സ്ഥലത്തോ.", "ഹിജ്രയുടെ സമയത്ത് നബി (സ) യെ ദുആ പഠിപ്പിച്ചിരുന്നു."),
        "dua_q_la_tadharni_fardan" to DuaText("സകരിയയുടെ ദുആ (എ. എസ്)-എന്നെ തനിച്ചാക്കരുത്.", "എൻറെ രക്ഷിതാവേ, എന്നെ വെറുതെ വിടരുത്. നീയാണ് ഏറ്റവും നല്ല അനന്തരാവകാശികൾ.", "കുട്ടികളെ തേടുന്നവർക്ക്.", "ഈ ദുആയിലൂടെ അല്ലാഹു യാഹ്യാ (അസ്) നൽകി."),
        "dua_q_munzalan_mubarakan" to DuaText("ഒരു അനുഗ്രഹീത ലാൻഡിംഗ് സ്ഥലം", "എൻറെ രക്ഷിതാവേ, ഞാൻ ഒരു അനുഗ്രഹീതമായ ലാൻഡിംഗ് സ്ഥലത്ത് ഇറങ്ങാൻ അനുവദിക്കുക. നീയാണ് ഭൂമിയിലേക്ക് കൊണ്ടുവരുന്നവരിൽ ഏറ്റവും നല്ലത്.", "ഒരു പുതിയ വീട്ടിലേക്ക് മാറുമ്പോഴോ എവിടെയെങ്കിലും നിർത്തുമ്പോഴോ-നൂഹിൻറെ (എ. എസ്) ദുആ.", "ഒരു പുതിയ സ്ഥലത്ത് അനുഗ്രഹത്തിനുള്ള ഒരു ദുആ."),
        "dua_q_amanna_faghfir" to DuaText("ഞങ്ങൾ വിശ്വസിക്കുന്നു, അതിനാൽ ഞങ്ങളോട് ക്ഷമിക്കണമേ.", "ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങൾ വിശ്വസിച്ചിരിക്കുന്നു. അതിനാൽ നീ ഞങ്ങൾക്ക് മാപ്പ് നൽകുകയും ഞങ്ങളോട് കരുണ കാണിക്കുകയും ചെയ്യേണമേ. നീയാണ് ഏറ്റവും നല്ല കരുണാനിധിയായവൻ.", "അല്ലാഹുവിൻറെ സൽക്കർമ്മികളായ ദാസന്മാരുടെ ദുആ.", "ക്ഷമയ്ക്കും കരുണയ്ക്കുമുള്ള സമഗ്രമായ ദുആ."),
        "dua_q_isrif_jahannam" to DuaText("നരകശിക്ഷ ഒഴിവാക്കുക", "ഞങ്ങളുടെ രക്ഷിതാവേ, നരകശിക്ഷ ഞങ്ങളിൽനിന്ന് ഒഴിവാക്കേണമേ. തീർച്ചയായും അതിൻറെ ശിക്ഷ നിത്യവാസമാണ്. തീർച്ചയായും അതൊരു ദുഷിച്ച വാസസ്ഥലവും വാസസ്ഥലവുമാണ്.", "പരമകാരുണികൻറെ ('ഇബ്ദ് അർ റഹ്മാൻ) ദാസന്മാരുടെ ദുആ.", "നരകത്തിൽ നിന്നുള്ള അഭയത്തിനുള്ള ഖുർആൻ ദുആ."),
        "dua_q_hab_li_hukman" to DuaText("ഇബ്രാഹിമിൻറെ (അ. സ.) ദുആ-ജ്ഞാനവും ജന്നത്തും", "എൻറെ കർത്താവേ, എനിക്ക് ജ്ഞാനം നൽകുകയും നീതിമാന്മാരോടൊപ്പം എന്നോടൊപ്പം ചേരുകയും ചെയ്യുക, പിൽക്കാല തലമുറകൾക്കിടയിൽ എനിക്ക് മാന്യമായ പരാമർശം നൽകുക, എന്നെ ആനന്ദത്തിന്റെ തോട്ടത്തിൻറെ അനന്തരാവകാശികളിൽ ഒരാളാക്കുക.", "നീതിമാന്മാരുടെയും പറുദീസയുടെയും കൂട്ടമായ ജ്ഞാനം തേടുന്നു.", "ഇബ്രാഹിം (അ. സ.) യുടെ സമഗ്രമായ ഒരു ദുആ."),
        "dua_q_lut_najjini_ahli" to DuaText("ലുത് (എ. എസ്)-എൻ്റെ കുടുംബത്തെ രക്ഷിക്കൂ", "എൻറെ രക്ഷിതാവേ, എന്നെയും എൻറെ കുടുംബത്തെയും അവർ പ്രവർത്തിക്കുന്നതിൻറെ അനന്തരഫലത്തിൽ നിന്ന് രക്ഷിക്കേണമേ.", "തിന്മയുടെ അന്തരീക്ഷത്തിൽ നിന്ന് ഒരാളുടെ കുടുംബത്തെ സംരക്ഷിക്കുക.", "തിന്മയിൽ നിന്ന് കുടുംബത്തെ സംരക്ഷിക്കുക."),
        "dua_q_sulaiman_awzini" to DuaText("നന്ദിക്കായി സുലൈമാൻ (എ. എസ്)-ൻറെ ദുആ", "എൻറെ രക്ഷിതാവേ, എനിക്കും എൻറെ മാതാപിതാക്കൾക്കും നീ നൽകിയ അനുഗ്രഹത്തിന് നന്ദിയുള്ളവനായിരിക്കുവാനും, നിനക്ക് ഇഷ്ടമുള്ള സൽകർമ്മങ്ങൾ ചെയ്യാനും, നിൻറെ കാരുണ്യത്താൽ എന്നെ നിൻറെ സൽക്കർമ്മക്കാരുടെ കൂട്ടത്തിൽ ഉൾപ്പെടുത്തുവാനും എന്നെ അനുവദിക്കേണമേ.", "അനുഗ്രഹങ്ങൾക്ക് നന്ദിയുള്ളവരായിരിക്കാനുള്ള കഴിവിന്.", "സുലൈമാൻ (എ. എസ്)-ൻറെ നന്ദിയുടെ ദുആ."),
        "dua_q_musa_zalamtu" to DuaText("മൂസയുടെ ദുആ (എ. എസ്)-ഞാൻ എന്നോട് തന്നെ തെറ്റ് ചെയ്തു.", "എൻറെ രക്ഷിതാവേ, ഞാൻ എന്നോട് തന്നെ അനീതി ചെയ്തിരിക്കുന്നു. അതിനാൽ എന്നോട് നീ ക്ഷമിക്കണമേ.", "ഒരു തെറ്റിന് ശേഷം ഉടനടി പശ്ചാത്താപം.", "മൂസാ (അ. സ.) യോട് അല്ലാഹു മാപ്പ് നൽകി."),
        "dua_q_musa_najjini" to DuaText("മൂസയുടെ ദുആ (എ. എസ്)-അടിച്ചമർത്തുന്നവരിൽ നിന്ന് എന്നെ രക്ഷിക്കുക", "എൻറെ രക്ഷിതാവേ, അക്രമികളായ ജനങ്ങളിൽനിന്ന് എന്നെ രക്ഷിക്കേണമേ.", "അടിച്ചമർത്തുന്നവരെ ഭയപ്പെടുമ്പോൾ.", "ഈജിപ്ത് വിടുമ്പോൾ മൂസയുടെ (എ. എസ്) ദുആ."),
        "dua_q_lut_unsurni" to DuaText("ലൂത്ത് (എ. എസ്)-അഴിമതിക്കാർക്കെതിരെ സഹായം", "എൻറെ കർത്താവേ, ദുഷിപ്പിക്കുന്ന ജനങ്ങളിൽനിന്ന് എന്നെ സഹായിക്കണമേ.", "അഴിമതി പ്രചരിപ്പിക്കുന്നവർക്കെതിരെ സഹായത്തിനായി.", "സത്യത്തിൽ ഉറച്ചുനിൽക്കുന്നവരുടെ ദുആ."),
        "dua_q_hab_li_salihin" to DuaText("നീതിമാനായ ഒരു കുട്ടിക്ക് വേണ്ടി ഇബ്രാഹിം (അ. സ.)-ൻറെ ദുആ", "എൻറെ രക്ഷിതാവേ, എനിക്ക് സൽക്കർമ്മങ്ങളിൽ നിന്ന് ഒരു സന്തതി (സന്തതി) നൽകേണമേ.", "നീതിമാന്മാരായ കുട്ടികളോട് ചോദിക്കുന്നു.", "ഇതിലൂടെ ഇസ്മായിൽ (എ. എസ്) അനുവദിച്ചു."),
        "dua_q_wasita_kulla_shay" to DuaText("സിംഹാസനം വഹിക്കുന്ന ദൂതന്മാരുടെ ദുവാ", "ഞങ്ങളുടെ രക്ഷിതാവേ, നീ എല്ലാറ്റിനെയും കാരുണ്യത്തിലും അറിവിലും ഉൾക്കൊള്ളുന്നു. അതിനാൽ പശ്ചാത്തപിക്കുകയും നിൻറെ മാർഗം പിന്തുടരുകയും നരകശിക്ഷയിൽ നിന്ന് അവരെ സംരക്ഷിക്കുകയും ചെയ്യുന്നവരോട് നീ പൊറുത്തുകൊടുക്കുക.", "സിംഹാസനം വഹിക്കുന്ന മാലാഖമാർ വിശ്വാസികൾക്കായി ഈ ദുആ നിർമ്മിക്കുന്നു.", "മാലാഖമാരുടെ ദുആയിൽ ഉൾപ്പെടുത്തുക എന്ന ഉദ്ദേശ്യത്തോടെ പാരായണം ചെയ്തു."),
        "dua_q_ikhwanina" to DuaText("നമുക്ക് മുൻപുള്ള നമ്മുടെ സഹോദരന്മാർക്ക്", "ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങൾക്കും വിശ്വാസത്തിൽ ഞങ്ങൾക്ക് മുമ്പ് പ്രവർത്തിച്ച ഞങ്ങളുടെ സഹോദരങ്ങൾക്കും നീ പൊറുത്തുതരേണമേ. വിശ്വസിച്ചവരോട് ഞങ്ങളുടെ ഹൃദയങ്ങളിൽ നീ ഒരു വിദ്വേഷവും ഉണ്ടാക്കരുത്. ഞങ്ങളുടെ രക്ഷിതാവേ, നീ തീർച്ചയായും കാരുണ്യവാനും കരുണാനിധിയുമാകുന്നു.", "മുമ്പ് വന്ന വിശ്വാസികൾക്കും ശുദ്ധമായ ഹൃദയത്തിനും വേണ്ടിയുള്ള ഒരു ദുആ.", "കുലീനരായ സഹപാഠികൾക്കും (ആർ. എ.) മുൻ വിശ്വാസികൾക്കും വേണ്ടിയുള്ള ഒരു ദുആ."),
        "dua_q_alayka_tawakkalna" to DuaText("ഞങ്ങൾ നിന്നെ ആശ്രയിക്കുന്നു (ഇബ്രാഹിം അ. സ.)", "ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങൾ അങ്ങയിൽ ആശ്രയിക്കുന്നു. അങ്ങയിലേക്കാണ് ഞങ്ങൾ മടങ്ങുന്നത്. അങ്ങയിലേക്കാണ് മടക്കം. ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങളെ സത്യനിഷേധികൾക്ക് പരീക്ഷയായി മാറ്റരുത്. ഞങ്ങളോട് നീ പൊറുത്തുതരേണമേ. ഞങ്ങളുടെ രക്ഷിതാവേ, തീർച്ചയായും നീ പ്രതാപിയും യുക്തിമാനുമായിരിക്കുന്നു.", "ഇബ്രാഹിം (അ. സ.)-ന്റെയും കൂട്ടാളികൾക്കും നൽകിയ ദുആ.", "അല്ലാഹുവിൽ ആശ്രയിക്കുന്നതിനും അവൻറെ അടുത്തേക്ക് തിരിയുന്നതിനുമുള്ള ഒരു ദ്വയം."),
        "dua_q_atmim_nurana" to DuaText("നമ്മുടെ പ്രകാശം പരിപൂർണ്ണമാക്കുക", "ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങളുടെ പ്രകാശം ഞങ്ങൾക്ക് വേണ്ടി പരിപൂർണ്ണമാക്കുകയും, ഞങ്ങൾക്ക് നീ പൊറുത്തുതരികയും ചെയ്യേണമേ. തീർച്ചയായും നീ എല്ലാറ്റിനും കഴിവുള്ളവനാകുന്നു.", "ഉയിർത്തെഴുന്നേൽപിൻറെ നാളിൽ വിശ്വാസികളുടെ ദുആ.", "സിറാത്തിൽ വെളിച്ചം ആവശ്യപ്പെടുന്നു."),
        "dua_q_asiya_baytan" to DuaText("ദുവ ഓഫ് ഏഷ്യ-ജന്നയിലെ ഒരു വീട്", "എൻറെ രക്ഷിതാവേ, എനിക്ക് വേണ്ടി നിനക്ക് സമീപം സ്വർഗത്തിൽ ഒരു ഭവനം പണിതു തരിക. ഫറവോനിൽ നിന്നും അവൻറെ പ്രവൃത്തികളിൽ നിന്നും എന്നെ രക്ഷിക്കേണമേ. അക്രമികളായ ജനങ്ങളിൽ നിന്ന് എന്നെ രക്ഷിക്കേണമേ.", "ഫറവോന്റെ ഭാര്യയായ ആസിയയുടെ ദൂഹ.", "അല്ലാഹു അവളെ വിശ്വാസികൾക്ക് ഒരു മാതൃകയാക്കി."),
        "dua_adhan_response" to DuaText("അദാനിനോട് പ്രതികരിക്കുക", "അല്ലാഹുവല്ലാതെ മറ്റൊരു ശക്തിയും ശക്തിയുമില്ല.", "'ഹയ'അലാസ്-സലഹയിലും'ഹയ'അലൽ-ഫലഹിലും'മുയസിൻ പറയുന്നത് ആവർത്തിക്കുക.", "ഹൃദയത്തിൽ നിന്ന് പ്രതികരിക്കുന്നവർ പറുദീസയിൽ പ്രവേശിക്കും."),
        "dua_adhan_shahadah" to DuaText("മുഅസ്സിൻറെ ഷഹാദയ്ക്ക് ശേഷം", "അല്ലാഹുവല്ലാതെ, പങ്കാളിയില്ലാതെ ആരാധിക്കപ്പെടാൻ ആർക്കും അവകാശമില്ലെന്നും മുഹമ്മദ് സൽഹ സല്ലല്ലാഹു അലൈഹി വസല്ലം അവൻറെ ദാസനും ദൂതനും ആണെന്നും ഞാനും സാക്ഷ്യം വഹിക്കുന്നു. അല്ലാഹുവിൻറെ രക്ഷിതാവെന്ന നിലയിൽ ഞാൻ സന്തുഷ്ടനാണ്. മുഹമ്മദ് സൽഹഅല്ലാഹു നബി ആയും ഇസ്ലാം മതമായും.", "വിശ്വാസത്തെക്കുറിച്ചുള്ള മുഅസിൻ്റെ സാക്ഷ്യം കേട്ടപ്പോൾ.", "അവന്റെ പാപങ്ങൾ ക്ഷമിക്കപ്പെടുന്നു."),
        "dua_istiftah_baid" to DuaText("ദുവാ തുറക്കുന്നുഃ എന്നെ പാപങ്ങളിൽ നിന്ന് അകറ്റുക", "അല്ലാഹുവേ, നീ കിഴക്ക് പടിഞ്ഞാറ് നിന്ന് അകറ്റിയതിനാൽ എൻറെ പാപങ്ങളിൽ നിന്ന് എന്നെ അകറ്റിനിർത്തുക. അല്ലാഹുവേ, ഒരു വെളുത്ത വസ്ത്രം അഴുക്ക് കൊണ്ട് ശുദ്ധീകരിക്കപ്പെടുന്നതുപോലെ എന്നെ പാപങ്ങളിൽ നിന്ന് ശുദ്ധീകരിക്കണമേ. അല്ലാഹുവേ, എൻറെ പാപങ്ങൾ വെള്ളവും മഞ്ഞും ആലിപ്പഴവും കൊണ്ട് കഴുകണമേ.", "ഉദ്ഘാടന തക്ബീറിന് ശേഷം (സനയ്ക്ക് പകരം പറയാം).", "പ്രവാചകൻ സൽഹുല്ലാഹ്ലാഹു സൽമാൻ തക്ബീറിനും പാരായണത്തിനും ഇടയിൽ ഇത് പാരായണം ചെയ്തു."),
        "dua_hamdan_kathiran" to DuaText("രുകുവിന് ശേഷം സമൃദ്ധമായ പ്രശംസ", "ഞങ്ങളുടെ കർത്താവേ, അങ്ങേയ്ക്ക് സ്തുതിയുണ്ട്-സമൃദ്ധവും ശുദ്ധവും അനുഗ്രഹീതവുമായ സ്തുതി.", "റുക്കുവിൽ നിന്ന് ഉയർന്നുവന്ന ശേഷം'റബ്ബന ലാകൽ-ഹംദ്'എന്ന ചിത്രത്തോടൊപ്പം.", "മുപ്പതിലധികം മാലാഖമാർ ഇത് ആദ്യമായി റെക്കോർഡ് ചെയ്യുന്നതിനായി ഓടുകയായിരുന്നു."),
    )
}
